p='crates/shep-core/src/protocol/wire.rs'
s=open(p).read()
s=s.replace('''/// Enough of a reply to recover its id when the reply's own type does not
/// decode.
#[derive(serde::Deserialize)]
struct ReplyIdOnly {
    id: u64,
}
''','''/// Enough of a reply to recover its id when the reply's own type does not
/// decode.
///
/// Mirrors [`Reply`](crate::protocol::Reply)'s shape, an `id` beside a
/// `result` in serde's `Ok`/`Err` representation, with both payloads left
/// unread. A frame with an `id` but no such `result` is not a reply.
#[derive(serde::Deserialize)]
struct ReplyIdOnly {
    id: u64,
    #[allow(dead_code)] // read by the derive only, to require the field's shape
    result: ResultShape,
}

/// The two arms of `Result`'s wire form, payloads ignored.
#[derive(serde::Deserialize)]
#[allow(dead_code)] // never read; deserialization is the check
enum ResultShape {
    Ok(serde::de::IgnoredAny),
    Err(serde::de::IgnoredAny),
}
''')
open(p,'w').write(s)
E
